import source from './bakeries.en.js';
const grid = (heads, rows) => `<table class="va-guide-grid va-guide-grid--wrap">
<thead><tr>${heads.map((h) => `<th scope="col">${h}</th>`).join('')}</tr></thead>
<tbody>${rows.map((row) => `<tr>${row.map((cell, i) => `<td data-label="${heads[i]}">${cell}</td>`).join('')}</tr>`).join('\n')}</tbody>
</table>`;
const pages = {};
function add(key, title, h1, crumb, eyebrow, description, lead, sections, faq) {
 const original = source[key];
 if (sections.length !== original.sections.length || faq.length !== original.faq.length) throw new Error(`Count mismatch: ${key}`);
 pages[key] = {...original, title, h1, crumb, eyebrow, description, lead, sections: sections.map(([title,html],i)=>({...original.sections[i],title,...(html === undefined ? {} : {html})})), faq: faq.map(([q,a])=>({q,a}))};
}
add('tetrapak', 'Wie viel können Sie mit 1 L Aquafaba zubereiten?', 'Wie viel können Sie mit 1 L Aquafaba zubereiten?', '{liquid_1l_label}', 'Flüssiges Aquafaba und Gebinde',
'Ein {liquid_1l_label} Aquafaba reicht für {meringue_batches_1l} Ansätze Baiser, {mayonnaise_batches_1l} Ansätze Mayonnaise oder {cocktails_batches_1l} Cocktails. Alle Ergiebigkeiten, Lagerfristen und Bezugsquellen.',
'Sie öffnen einen {liquid_1l_label} für ein Blech Baiser und verwenden das angebrochene Gebinde noch in derselben Woche für Mousse, Mayonnaise oder mehrere Sours. Dafür eignet sich das 1 L Format: Sie können den Inhalt an mehreren Produktionstagen für unterschiedliche Zubereitungen nutzen. Ein Tetrapak reicht für {meringue_batches_1l} Ansätze Baiser, {mayonnaise_batches_1l} Ansätze Mayonnaise, {chocolate_mousse_batches_1l} vollständige Ansätze Schokoladenmousse oder {cocktails_batches_1l} Cocktails. Vergleichen Sie diese Mengen mit Ihrer laufenden Produktion und prüfen Sie, ob Sie den Inhalt innerhalb von {opened_days} Tagen verbrauchen.',
[
['Was können Sie mit einem 1 L Tetrapak zubereiten?', `${grid(['Zubereitung', 'Aus einem {liquid_1l_label}'], [['Baiser','{meringue_batches_1l} Ansätze, etwa {liquid_1l_meringues} Baisers'],['Mayonnaise','{mayonnaise_batches_1l} Ansätze'],['Schokoladenmousse','{chocolate_mousse_batches_1l} vollständige Ansätze'],['Cocktails','{cocktails_batches_1l} Drinks']])}
<p>In der Patisserie lässt sich der Inhalt auf Mousse und Baiser aufteilen, an der Bar vollständig für Sours verwenden. Ob Sie <a href="{meringue_href}">Baiser aufschlagen</a>, <a href="{mayonnaise_href}">Mayonnaise zubereiten</a> oder <a href="{chocolate_mousse_href}">Schokoladenmousse herstellen</a>: Behalten Sie die Methode des jeweiligen Rezepts bei, unabhängig von der Gebindegröße.</p>`],
['Warum eignet sich flüssiges Aquafaba für den regelmäßigen Einsatz?', `<p>Flüssiges Aquafaba ist gebrauchsfertig. Sie müssen es daher nicht anrühren, bevor Sie es für ein Rezept abwiegen. Um ein Eiweiß zu ersetzen, verwenden Sie {white_liquid} g flüssiges VERY AQUAFABA. Wenn Aquafaba ein ganzes Ei zur Bindung oder für Feuchtigkeit ersetzt, verwenden Sie {egg_liquid} g.</p>
<p>An der Bar sehen die Cocktailrezepte {cocktails_dose} ml pro Drink vor. Bei dieser Dosierung reicht ein Tetrapak für {cocktails_batches_1l} Cocktails. Passt das zu Ihrem Ausschank, können Sie <a href="{cocktails_href}">Cocktails mit Aquafaba shaken</a>, das Sie direkt aus dem gekühlten Gebinde dosieren.</p>`],
['Verbrauchen Sie ein geöffnetes 1 L Gebinde rechtzeitig?', `<p>Lagern Sie das flüssige Aquafaba nach dem Öffnen bei {opened_temp} °C und verbrauchen Sie es innerhalb von {opened_days} Tagen. Vergleichen Sie diese Frist mit der Ergiebigkeit: {meringue_batches_1l} Ansätze Baiser oder {cocktails_batches_1l} Cocktails lassen sich in einem Betrieb problemlos innerhalb dieser Zeit zubereiten und sind für einen anderen deutlich zu viel.</p>
<p>Wenn Sie das flüssige Aquafaba nicht innerhalb von {opened_days} Tagen aufbrauchen, können Sie mit <a href="{powder_href}">Pulver</a> genau die Menge anrühren, die Sie für den nächsten Ansatz benötigen. <a href="{storage_href}">Prüfen Sie die Lagerbedingungen für geöffnetes Aquafaba</a>, wenn Sie die beiden Formen vergleichen.</p>`],
['Verbrauchen Sie in wenigen Tagen mehr als einen Tetrapak?', `<p>Ein größeres Gebinde kommt infrage, wenn Sie innerhalb desselben Produktionszeitraums regelmäßig mehr als einen {liquid_1l_label} verbrauchen. <a href="{bib_href}">Der {liquid_10l_label}</a> ist für den kontinuierlichen Einsatz von flüssigem Aquafaba gedacht, weniger für gelegentliche Ansätze. Reicht ein Tetrapak bequem für mehrere Produktionstage, bleiben Sie bei 1 L.</p>`],
['Wo können Sie den 1 L Tetrapak kaufen?', `<p>Den {liquid_1l_label} erhalten Sie über Amazon in den USA, Deutschland und Österreich, InstantChef in Frankreich und Qualifirst in Kanada. Für andere Länder <a href="{where_to_buy_href}">senden Sie eine Kaufanfrage</a> und nennen Sie Ihren Standort und die geplante Zubereitung.</p>`]
], [
['Wie viele Baisers kann ich mit 1 L Aquafaba zubereiten?', 'Ein {liquid_1l_label} reicht für {meringue_batches_1l} Ansätze Baiser, also etwa {liquid_1l_meringues} Baisers.'],
['Wie viele Ansätze Mayonnaise kann ich mit 1 L zubereiten?', 'Ein {liquid_1l_label} reicht für {mayonnaise_batches_1l} Ansätze Mayonnaise mit jeweils {mayonnaise_dose} g Aquafaba.'],
['Wie viele Ansätze Schokoladenmousse kann ich mit 1 L zubereiten?', 'Bei einem Ansatz mit {chocolate_mousse_eggs} Eiweiß reicht ein {liquid_1l_label} für {chocolate_mousse_batches_1l} vollständige Ansätze Schokoladenmousse.'],
['Wie viele Cocktails kann ich mit 1 L Aquafaba zubereiten?', 'Bei den in den Cocktailrezepten vorgesehenen {cocktails_dose} ml pro Drink reicht ein {liquid_1l_label} für {cocktails_batches_1l} Cocktails.'],
['Wie lange hält sich ein geöffnetes 1 L Gebinde?', 'Lagern Sie es bei {opened_temp} °C und verbrauchen Sie den Inhalt innerhalb von {opened_days} Tagen.'],
['Wo kann ich den 1 L Tetrapak kaufen?', 'Amazon führt ihn in den USA, Deutschland und Österreich, InstantChef in Frankreich und Qualifirst in Kanada. Für andere Länder senden Sie eine Anfrage mit Ihrem Land und der geplanten Zubereitung.']
]);
add('bib', 'Passt ein 10 L Bag-in-Box Aquafaba zu Ihrem Betrieb?', 'Passt ein 10 L Bag-in-Box Aquafaba zu Ihrem Betrieb?', '{liquid_10l_label}', 'Flüssiges Aquafaba und Gebinde',
'Ein {liquid_10l_label} Aquafaba ersetzt {liquid_10l_whites} Eiweiß. Für wen sich das Gebinde eignet, welche Produktionsmengen es abdeckt und wie Sie ein gewerbliches Angebot anfordern.',
'Wenn Sie im Service oder in der Produktion einen {liquid_1l_label} nach dem anderen öffnen, passt das kleinere Gebinde möglicherweise nicht mehr zu Ihrem Arbeitsablauf. Der {liquid_10l_label} ist für den kontinuierlichen Einsatz gedacht: in Hotelküchen, an Bars mit regelmäßigem Sour-Ausschank, in der Getränkeherstellung oder in Gastronomiebetrieben, die täglich flüssiges Aquafaba verwenden. Er ersetzt {tetrapaks_in_10l} Tetrapaks und entspricht {liquid_10l_whites} Eiweiß. Entscheidend ist, ob Sie diese Menge innerhalb derselben Frist von {opened_days} Tagen nach dem Öffnen verbrauchen können.',
[
['Verwenden Sie flüssiges Aquafaba bereits täglich?', `<p>Wählen Sie 10 L, wenn Sie flüssiges Aquafaba im Service oder in der Produktion bereits laufend einsetzen. Eine Hotelgruppe kann es in mehreren Küchen verwenden. Eine Bar serviert möglicherweise während des gesamten Service Sours. In einer Getränkeproduktion oder einer Großküche kann dieselbe Flüssigkeit in wiederholten Produktionsdurchläufen eingesetzt werden.</p>
<p>In all diesen Fällen verbrauchen Sie das geöffnete Aquafaba regelmäßig, statt es zwischen gelegentlichen Ansätzen zu lagern.</p>`],
['Welche Produktionsmengen decken 10 L ab?', `${grid(['Verwendung in der Produktion', 'Aus einem {liquid_10l_label}'], [['Baiser','{meringue_batches_10l} Ansätze'],['Mayonnaise','{mayonnaise_batches_10l} Ansätze'],['Cocktails','{cocktails_batches_10l} Sours'],['1 L Tetrapaks','{tetrapaks_in_10l} Packungen']])}
<p>Vergleichen Sie diese Zahlen mit Ihrer üblichen Produktion über mehrere Tage. In der Patisserie können Sie aus demselben Vorrat <a href="{meringue_href}">mehrere Ansätze Baiser herstellen</a>, an der Bar <a href="{cocktails_href}">während des Service Sours ausschenken</a>, ohne einen weiteren Tetrapak zu öffnen.</p>`],
['Ändert sich etwas am Rezept?', `<p>Nein. Verwenden Sie {white_liquid} g flüssiges VERY AQUAFABA für jedes Eiweiß, das Sie ersetzen möchten. Mit dem größeren Gebinde ändert sich Ihr Vorrat, nicht das Mengenverhältnis oder die Zubereitung. Ob Sie <a href="{mayonnaise_href}">Mayonnaise herstellen</a>, Baiser aufschlagen oder Aquafaba in einer anderen bewährten Zubereitung verwenden: Behalten Sie die jeweilige Methode bei.</p>`],
['Können Sie 10 L innerhalb von {opened_days} Tagen verbrauchen?', `<p>Geöffnetes flüssiges VERY AQUAFABA wird bei {opened_temp} °C gelagert und innerhalb von {opened_days} Tagen verbraucht. Wählen Sie 10 L nur, wenn Sie den Inhalt innerhalb dieser Frist aufbrauchen können. Das setzt in der Regel voraus, dass Sie es laufend im Service oder in mehreren Produktionsdurchläufen einsetzen, statt auf den nächsten gelegentlichen Ansatz zu warten.</p>
<p>Wäre der rechtzeitige Verbrauch schwierig, ist <a href="{tetrapak_href}">der {liquid_1l_label}</a> die passendere Menge für ein geöffnetes Gebinde. <a href="{storage_href}">Prüfen Sie die Lagerbedingungen für geöffnetes Aquafaba</a>, bevor Sie entscheiden, welche Gebindegröße zu Ihrem Produktionsrhythmus passt.</p>`],
['Wie erhalten Sie ein Angebot für 10 L?', `<p>Für den {liquid_10l_label} erstellen wir ein Angebot auf Anfrage; er wird nicht als übliche Einzelhandelspackung verkauft. Wenn Sie <a href="{where_to_buy_href}">ein Angebot für 10 L anfordern</a> möchten, wählen Sie im Kaufbereich unten die Option für Geschäftskunden. Nennen Sie Ihr Land, Ihre Anwendung und Ihren ungefähren Aquafaba-Verbrauch. Sie erhalten unser Angebot, das technische Datenblatt sowie Mindestbestellmenge und Lieferzeit für Ihren Markt.</p>`]
], [
['Wie viele Eiweiß ersetzt ein 10 L Bag-in-Box?', 'Ein {liquid_10l_label} ersetzt bei {white_liquid} g pro Eiweiß insgesamt {liquid_10l_whites} Eiweiß.'],
['Für wie viele Ansätze Baiser reichen 10 L?', 'Ein {liquid_10l_label} reicht für {meringue_batches_10l} Ansätze Baiser mit jeweils {meringue_dose} g.'],
['Für wie viele Ansätze Mayonnaise reichen 10 L?', 'Ein {liquid_10l_label} reicht für {mayonnaise_batches_10l} Ansätze Mayonnaise.'],
['Wie viele Cocktails kann ich mit 10 L zubereiten?', 'Bei den in den Cocktailrezepten vorgesehenen {cocktails_dose} ml pro Drink reicht ein {liquid_10l_label} für {cocktails_batches_10l} Sours.'],
['Für wen eignet sich das 10 L Format?', 'Wählen Sie es, wenn Sie flüssiges Aquafaba bereits kontinuierlich im Service oder in der Produktion verwenden, etwa in Hotelküchen, der Getränkeherstellung, der Gastronomie oder einer Bar mit regelmäßigem Sour-Ausschank.'],
['Wie erfahre ich den Preis für 10 L?', 'Senden Sie eine gewerbliche Anfrage mit Ihrem Land, Ihrer Anwendung und dem voraussichtlichen Verbrauch. Sie erhalten unser Angebot, das technische Datenblatt, die Mindestbestellmenge und die Lieferzeit.']
]);
add('ibc', 'Aquafaba im 1 t IBC: Was Sie vor der Bestellung wissen sollten', 'Was sollten Sie vor der Bestellung eines 1 t IBC Aquafaba wissen?', '{liquid_1t_label}', 'Flüssiges Aquafaba und Gebinde',
'Ein {liquid_1t_label} Aquafaba entspricht {liquid_1t_whites} Eiweiß. Wann er zu einer etablierten Produktion passt, was Sie auf Anfrage erhalten und was vor der Bestellung zu klären ist.',
'Sie haben das Rezept getestet, die Dosierung festgelegt und Aquafaba in Ihre regelmäßige Produktion aufgenommen. Kleinere Gebinde bedeuten nun wiederholte Bestellungen, zusätzliche Handgriffe und mehr Verpackung für eine bereits fest eingeplante Zutat. Für diese Produktionsphase eignet sich ein {liquid_1t_label}. Er entspricht {liquid_1t_whites} Eiweiß; dabei gilt dasselbe Mengenverhältnis von {white_liquid} g wie bei den kleineren Flüssiggebinden. Prüfen Sie vor der Bestellung, ob die Menge Ihrem Verbrauch entspricht, welche Voraussetzungen Ihr Betrieb für die Handhabung benötigt und welche Bestelldetails wir für Ihren Markt bestätigen müssen.',
[
['Sind Rezept und Herstellungsprozess bereits etabliert?', `<p>Ziehen Sie einen IBC erst in Betracht, wenn Rezept und Produktionsverfahren feststehen. Er kann sich für einen Standort eignen, der regelmäßig dasselbe eifreie Produkt herstellt, für eine zentrale Produktion mit mehreren Linien oder für einen Hersteller, der Aquafaba bereits validiert hat und nun ein größeres Gebinde benötigt.</p>
<p>Wenn Sie die Anwendung noch entwickeln, <a href="{index_href}">testen Sie zunächst im Rezeptmaßstab</a>. Wechseln Sie zum IBC, sobald Aquafaba fest zum Prozess gehört.</p>`],
['Wie passen {liquid_1t_whites} Eiweiß zu Ihrer Produktionsmenge?', `<p>Ein {liquid_1t_label} entspricht {liquid_1t_whites} Eiweiß. Vergleichen Sie diese Zahl direkt mit der Menge an Eiweiß, die Sie in Ihrer Produktion bereits ersetzen. Liegt Ihr Verbrauch in dieser Größenordnung, lohnt sich ein Gespräch über den IBC.</p>
<p>Bei geringerem Bedarf <a href="{bib_href}">vergleichen Sie den {liquid_10l_label}</a> für den kontinuierlichen gewerblichen Einsatz oder <a href="{tetrapak_href}">den {liquid_1l_label}</a> für kleinere Mengen.</p>`],
['Ändert sich das Mengenverhältnis in dieser Größenordnung?', `<p>Nein. Das flüssige Aquafaba bleibt gebrauchsfertig; pro zu ersetzendem Eiweiß verwenden Sie weiterhin {white_liquid} g VERY AQUAFABA. Beim Wechsel auf einen IBC ändert sich das Liefergebinde, nicht das Mengenverhältnis im Rezept. Erproben Sie die Anwendung in einem kleineren Gebinde, bevor Sie Bestellung und Handhabung der Zutat umstellen.</p>`],
['Welche Angaben gehören in Ihre Anfrage?', `<p>Nennen Sie Ihr Land, die Anwendung und die voraussichtliche Verbrauchsmenge. Ergänzen Sie Fragen zur Handhabung des IBC an Ihrem Standort. Falls ein Anschluss, ein Dosierschritt oder ein anderer Teil Ihrer Anlage geklärt werden muss, sprechen Sie ihn an, statt von einer Annahme auszugehen.</p>
<p>Sie erhalten von uns das technische Datenblatt, die Mindestbestellmenge und die Lieferzeit für Ihren Markt. <a href="{where_to_buy_href}">Senden Sie die bereits bekannten Produktionsangaben</a> über die Geschäftskundenoption im Kaufbereich unten. So können wir die praktischen Fragen vor Ihrer Bestellung beantworten.</p>`]
], [
['Wie viele Eiweiß ersetzt ein 1 t IBC?', 'Ein {liquid_1t_label} entspricht bei {white_liquid} g pro Eiweiß insgesamt {liquid_1t_whites} Eiweiß.'],
['Ist das Aquafaba im IBC gebrauchsfertig?', 'Ja. Flüssiges VERY AQUAFABA wird in jeder Gebindegröße gebrauchsfertig geliefert.'],
['Ändert sich das Mengenverhältnis im industriellen Maßstab?', 'Nein. Verwenden Sie {white_liquid} g flüssiges VERY AQUAFABA für jedes Eiweiß, das Sie ersetzen möchten.'],
['Welche Informationen kann ich vor der Bestellung eines IBC anfordern?', 'Fragen Sie nach dem technischen Datenblatt, der Mindestbestellmenge und der Lieferzeit. Ergänzen Sie alle Fragen zur Handhabung, die sich für Ihre Anlage ergeben.'],
['Was sollte ich in meiner Anfrage angeben?', 'Ihr Land, die Anwendung, die erwartete Menge und alle praktischen Fragen, die wir für Ihre Produktionslinie klären sollen.']
]);
export default pages;
add('pavlova','Pavlova mit Aquafaba: Ein Boden mit 20 cm Durchmesser','Pavlova mit Aquafaba: Ein Boden mit {pavlova_diameter} cm Durchmesser','Pavlova','Anwendungsleitfaden',
'Ein Pavlovaboden mit {pavlova_aquafaba} g Aquafaba und {pavlova_sugar} g Zucker, getrocknet bei {pavlova_oven} °C: Zutaten, Zubereitung, Vorbereitung und Fehlerbehebung.',
'Sie benötigen einen Pavlovaboden, der außen knusprig und innen weich bleibt. Für einen Boden mit {pavlova_diameter} cm Durchmesser verwenden Sie {pavlova_aquafaba} g gekühltes VERY AQUAFABA, entsprechend {pavlova_whites} Eiweiß, und {pavlova_sugar} g feinen Zucker. Bei Pulver rühren Sie zunächst {pavlova_powder} g mit {pavlova_water} ml Wasser an. Stärke, Säure sowie die Schritte beim Trocknen und Abkühlen unterscheiden diesen Boden von einem gewöhnlichen durchgetrockneten Baiser.',
[
['Was benötigen Sie für einen Boden?',`${grid(['Zutat','Menge'],[['VERY AQUAFABA','{pavlova_aquafaba} g'],['Feiner Zucker','{pavlova_sugar} g'],['Maisstärke','{pavlova_cornstarch} g'],['Weißweinessig oder Zitronensaft','{pavlova_vinegar} g'],['Weinstein','{pavlova_tartar} g, optional'],['Zitronensäure','{pavlova_citric} g statt Weinstein, optional']])}
<p>Wenn Sie Pulver verwenden, rühren Sie {pavlova_powder} g mit {pavlova_water} ml Wasser an und kühlen Sie das angerührte Aquafaba. <a href="{pavlova_calc_href}">Berechnen Sie die Mengen mit dem Rechner</a>, wenn Sie mehrere Böden herstellen.</p>`],
['Wie bereiten Sie den Boden zu?',`<ol>
<li>Kühlen Sie das Aquafaba auf {pavlova_chill} °C.</li>
<li>Schlagen Sie es in einer sauberen, fettfreien Schüssel auf, bis sich weiche Spitzen bilden.</li>
<li>Geben Sie optional Weinstein oder Zitronensäure hinzu und schlagen Sie weiter.</li>
<li>Lassen Sie den feinen Zucker nach und nach einrieseln, bis die Baisermasse glänzend, fest und dicht ist.</li>
<li>Heben Sie Maisstärke und Essig oder Zitronensaft unter.</li>
<li>Formen Sie auf einem ausgelegten Blech eine Scheibe mit {pavlova_diameter} cm Durchmesser und leicht erhöhtem Rand.</li>
<li>Trocknen Sie den Boden bei {pavlova_oven} °C ohne Umluft für {pavlova_hours} Stunden.</li>
<li>Schalten Sie den Ofen aus und lassen Sie den Boden bei leicht geöffneter Tür darin abkühlen.</li>
<li>Geben Sie Creme und Obst erst unmittelbar vor dem Servieren darauf.</li>
</ol>
<p><a href="{pavlova_process_href}">Das Arbeitsblatt</a> stellt jedem Schritt seinen Referenzwert gegenüber und bietet eine Spalte für Ihren eigenen Ansatz.</p>`],
['Backen Sie den Boden im Voraus?',`<p>Sie können den Boden {pavlova_ahead} Tag im Voraus backen. Bewahren Sie ihn bis zum Zusammensetzen luftdicht mit einem Trockenmittelbeutel auf. Geben Sie Creme und Obst erst zum Servieren darauf, da die Feuchtigkeit des Belags die Hülle weich werden lässt.</p>`],
['Wie oft stellen Sie Pavlova her?',`<p>Ein {liquid_1l_label} reicht für {pavlova_batches_1l} Böden. Wenn Sie so häufig Pavlova zubereiten, dass Sie das flüssige Aquafaba innerhalb von {opened_days} Tagen aufbrauchen, wiegen Sie pro Boden {pavlova_aquafaba} g direkt aus dem gekühlten Gebinde ab.</p>
<p>Steht Pavlova nur gelegentlich auf der Karte, bei Banketten oder in der Wochenendproduktion, können Sie mit <a href="{p_pavlova_href}">Pulver</a> das Aquafaba für die Böden des jeweiligen Backdurchgangs anrühren. Das übrige Pulver bleibt trocken im verschlossenen Beutel. <a href="{powder_href}">Vergleichen Sie die Pulverbeutel</a>, wenn Sie regelmäßig mit Pulver arbeiten.</p>`],
['Was prüfen Sie, wenn die Pavlova nicht gelingt?',`${grid(['Was Sie sehen','Ursache','Lösung'],[['Der Schaum erreicht nicht das gewünschte Volumen','Warmes Aquafaba oder Fett an den Geräten','Auf {pavlova_chill} °C kühlen und saubere Geräte verwenden'],['Die Hülle reißt beim Abkühlen','Zu schnelles Abkühlen','Im ausgeschalteten Ofen bei leicht geöffneter Tür abkühlen lassen'],['Der Boden ist durchgehend weich','Der Boden muss länger trocknen','Die vollen {pavlova_hours} Stunden bei {pavlova_oven} °C einhalten'],['Das Innere trocknet vollständig aus','Stärke und Säure fehlen oder der Boden wurde zu lange getrocknet','Beides unterheben; den Boden herausnehmen, solange das Innere noch nachgibt'],['Der Boden wird nach dem Belegen weich','Der Belag wurde zu früh aufgetragen','Creme und Obst erst zum Servieren auflegen']])}`]
], [
['Wie viel Aquafaba brauche ich für eine Pavlova?','{pavlova_aquafaba} g für einen Boden mit {pavlova_diameter} cm Durchmesser, entsprechend {pavlova_whites} Eiweiß.'],
['Wie viel Pulver brauche ich?','{pavlova_powder} g Pulver mit {pavlova_water} ml Wasser; vor dem Aufschlagen kühlen.'],
['Welche Temperatur verwende ich?','{pavlova_oven} °C ohne Umluft für {pavlova_hours} Stunden.'],
['Kann ich den Boden im Voraus backen?','Ja. Backen Sie ihn {pavlova_ahead} Tag im Voraus und bewahren Sie ihn luftdicht mit einem Trockenmittelbeutel auf.'],
['Warum gebe ich Stärke und Säure hinzu?','Sie sorgen für das weiche Innere unter der knusprigen Hülle. Heben Sie nach dem Zucker {pavlova_cornstarch} g Stärke und {pavlova_vinegar} g Essig oder Zitronensaft unter.']
]);
add('pavlova_calc','Wie viel Aquafaba brauchen Sie für Pavlova? Mengenrechner','Wie viel Aquafaba brauchen Sie für Pavlova?','Mengenrechner','Mengenrechner',
'Passen Sie die Pavlovamengen an Ihre Anzahl Böden an: flüssiges Aquafaba oder Pulver mit Wasser, Zucker, Stärke, Säure und Belag pro Boden sowie Böden pro Gebinde.',
'Jeder Pavlovaboden mit {pavlova_diameter} cm Durchmesser beruht auf demselben Referenzansatz: {pavlova_aquafaba} g Aquafaba, entsprechend {pavlova_whites} Eiweiß, mit {pavlova_sugar} g Zucker. Rechnen Sie die Zutaten mit dem Mengenrechner um. Ofentemperatur, Trocknungszeit und Größe der einzelnen Böden bleiben gleich.',
[
['Welche Mengen ändern sich mit der Anzahl der Böden?',`<p>Aquafaba, Zucker, Stärke, Säure, Creme und Obst werden entsprechend der Anzahl der Böden vervielfacht. Erhöhen Sie die Ofentemperatur nicht, nur weil Sie mehr Böden backen: Jeder Boden wird weiterhin bei {pavlova_oven} °C ohne Umluft für {pavlova_hours} Stunden getrocknet. Das Aquafaba wird unabhängig von der Ansatzgröße bei {pavlova_chill} °C aufgeschlagen.</p>
<p>Die Pulvermenge wird pro Eiweiß berechnet: {white_powder} g mit {white_water} ml Wasser für jedes der {pavlova_whites} Eiweiß eines Bodens. Das ergibt {pavlova_powder} g und {pavlova_water} ml pro Boden; vor dem Aufschlagen anrühren und kühlen.</p>`],
['Wie viele Böden können Sie mit jedem Gebinde herstellen?',`${grid(['Gebinde','Böden mit {pavlova_diameter} cm Durchmesser'],[['{liquid_1l_label}','{pavlova_batches_1l}'],['{liquid_10l_label}','{pavlova_batches_10l}'],['{small_pouch_g} g Beutel','{pavlova_batches_30g}'],['{medium_pouch_g} g Beutel','{pavlova_batches_200g}'],['{large_pouch_kg} kg Beutel','{pavlova_batches_3kg}']])}
<p>Nutzen Sie die Gebindetabelle für die Vorratsplanung und den Rechner für die Rezeptmengen. <a href="{pavlova_href}">Arbeiten Sie nach der Pavlova-Methode</a>, bevor Sie einen ersten Produktionsdurchlauf hochrechnen.</p>`],
['Rechenbeispiel: zehn Böden für ein Bankett',`<p>Für zehn Böden mit {pavlova_diameter} cm Durchmesser benötigen Sie {ten_bases_aquafaba} g flüssiges Aquafaba; dafür öffnen Sie {ten_bases_packs} Tetrapaks. Alternativ rühren Sie {ten_bases_powder} g Pulver aus einem {medium_pouch_g} g Beutel mit {ten_bases_water_l} L Wasser an. Hinzu kommen {ten_bases_sugar} g feiner Zucker sowie als Belag {ten_bases_cream_l} L aufgeschlagene pflanzliche Creme und {ten_bases_fruit_kg} kg Obst, die Sie erst zum Servieren auftragen.</p>
<p>Die Böden können Sie {pavlova_ahead} Tag zuvor backen und luftdicht mit einem Trockenmittelbeutel lagern; am Tag selbst werden sie nur noch zusammengesetzt. <a href="{pavlova_process_href}">Das Arbeitsblatt</a> führt für die Arbeit am Ofen jeden Schritt mit seinem Referenzwert auf.</p>`]
], [
['Wie viel Aquafaba brauche ich für zwei Böden?','{two_bases_aquafaba} g flüssiges Aquafaba oder {two_bases_powder} g Pulver mit {two_bases_water} ml Wasser.'],
['Verdoppelt sich die Trocknungszeit bei zwei Böden?','Nein. Verwenden Sie {pavlova_oven} °C ohne Umluft für {pavlova_hours} Stunden pro Boden.'],
['Wie viele Böden kann ich mit einem 200 g Beutel herstellen?','{pavlova_batches_200g}.'],
['Wird der Belag entsprechend der Anzahl der Böden berechnet?','Ja. Die Referenzmenge beträgt {pavlova_cream} ml Creme und {pavlova_fruit} g Obst pro Boden.']
]);
add('pavlova_process','Pavlova mit Aquafaba herstellen: Arbeitsblatt','Pavlova mit Aquafaba herstellen: Arbeitsblatt','Arbeitsblatt','Arbeitsblatt',
'Alle Schritte für den Pavlovaboden mit Aquafaba, mit Referenzwerten und Platz für Ihren Ansatz. Dazu Kontrollen, Ursachen und Lösungen. Zum Ausdrucken.',
'Nutzen Sie dieses Blatt am Arbeitsplatz, sobald die Rezeptzutaten abgewogen sind. Für eine andere Anzahl Böden rechnen Sie zunächst die Zutaten um. Reihenfolge und Zielzustände bleiben gleich: {pavlova_aquafaba} g Aquafaba bei {pavlova_chill} °C, {pavlova_sugar} g Zucker und {pavlova_oven} °C für {pavlova_hours} Stunden.',
[
['Was sollten Sie vor dem Aufschlagen vorbereiten?',`<p>Bevor Sie die Maschine starten: Aquafaba kühlen, Zucker abwiegen, Stärke und Säure abmessen, das Blech auslegen, einen Kreis mit {pavlova_diameter} cm Durchmesser markieren und den Ofen auf {pavlova_oven} °C ohne Umluft vorheizen. Sobald der Schaum fertig ist, arbeiten Sie unmittelbar weiter.</p>
<p><a href="{pavlova_calc_href}">Berechnen Sie zuerst die Mengen</a>, wenn Sie mehrere Böden herstellen; <a href="{pavlova_href}">die Pavlova-Anleitung</a> enthält das Rezept und Hinweise zur Fehlerbehebung.</p>`],
['So erkennen Sie das richtige Ergebnis in jedem Schritt',`<p>Zunächst weiche Spitzen, die sich neigen, dann feste Spitzen, die stehen bleiben. Nach der Zuckerzugabe ist die Baisermasse glänzend und dicht. Nach dem Unterheben ist sie nahezu unverändert. Aus dem Ofen kommt eine trockene, helle Hülle mit einem Inneren, das auf Fingerdruck leicht nachgibt. Nach dem Abkühlen zeigt die Oberfläche keinen durchgehenden Riss. Nach dem Belegen bleibt der Rand unter der Creme bis zum Servieren knusprig.</p>
<p>Haken Sie jeden Schritt erst ab, wenn der Zielzustand erreicht ist, nicht schon nach dem Ausführen. Fehlt dieser Zustand, halten Sie inne und prüfen Sie die Ursache, bevor der nächste Schritt sie verdeckt.</p>`]
], [
['Wann gebe ich den Zucker hinzu?','Sobald sich der erste Schaum gebildet hat, lassen Sie den Zucker beim Weiterschlagen nach und nach einrieseln, bis die Baisermasse glänzend, fest und dicht ist.'],
['Woran erkenne ich, dass der Boden ausreichend getrocknet ist?','Nach {pavlova_hours} Stunden bei {pavlova_oven} °C ist die Hülle außen knusprig, während das Innere leicht weich bleibt.'],
['Kann ich dieses Blatt auch mit Pulver verwenden?','Ja. Rühren Sie pro Boden {pavlova_powder} g mit {pavlova_water} ml Wasser an, kühlen Sie das Aquafaba und beginnen Sie dann mit Schritt 1.'],
['Wie weit im Voraus kann ich den Boden herstellen?','Bis zu {pavlova_ahead} Tag im Voraus, luftdicht mit einem Trockenmittelbeutel gelagert.']
]);
